-- Apply as one atomic D1 batch. No existing contract/payment/media rows are rewritten.
CREATE TABLE CheckoutCancellation (
 id TEXT PRIMARY KEY NOT NULL,
 orderId TEXT NOT NULL UNIQUE REFERENCES CheckoutOrder(id) ON DELETE RESTRICT,
 reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 500),
 createdBy TEXT NOT NULL REFERENCES User(id) ON DELETE RESTRICT,
 createdAt INTEGER NOT NULL CHECK(typeof(createdAt)='integer'),
 operationKey TEXT NOT NULL CHECK(length(operationKey) BETWEEN 16 AND 200),
 requestFingerprint TEXT NOT NULL CHECK(length(requestFingerprint)=64 AND requestFingerprint NOT GLOB '*[^0-9a-f]*'),
 financialSnapshot TEXT NOT NULL CHECK(json_valid(financialSnapshot) AND json_type(financialSnapshot)='object'),
 reservationSnapshot TEXT NOT NULL CHECK(json_valid(reservationSnapshot) AND json_type(reservationSnapshot)='array'),
 sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN(0,1)),
 UNIQUE(id,orderId), UNIQUE(createdBy,operationKey)
);
CREATE TABLE CheckoutStockRelease (
 id TEXT PRIMARY KEY NOT NULL,
 cancellationId TEXT NOT NULL, orderId TEXT NOT NULL,
 itemId TEXT NOT NULL UNIQUE REFERENCES CheckoutOrderItem(id) ON DELETE RESTRICT,
 variantId TEXT NOT NULL REFERENCES ProductVariant(id) ON DELETE RESTRICT,
 quantity INTEGER NOT NULL CHECK(typeof(quantity)='integer' AND quantity BETWEEN 1 AND 99),
 stockBefore INTEGER NOT NULL CHECK(typeof(stockBefore)='integer' AND stockBefore BETWEEN 0 AND 2147483647),
 stockAfter INTEGER NOT NULL CHECK(typeof(stockAfter)='integer' AND stockAfter=stockBefore+quantity AND stockAfter<=2147483647),
 createdAt INTEGER NOT NULL CHECK(typeof(createdAt)='integer'),
 FOREIGN KEY(cancellationId,orderId) REFERENCES CheckoutCancellation(id,orderId) ON DELETE RESTRICT
);
CREATE INDEX CheckoutStockRelease_order ON CheckoutStockRelease(orderId);
CREATE TRIGGER CheckoutCancellation_insert BEFORE INSERT ON CheckoutCancellation BEGIN SELECT CASE WHEN NEW.sealed<>0 OR NOT EXISTS(SELECT 1 FROM CheckoutOrder o JOIN CheckoutGroup g ON g.id=o.checkoutGroupId WHERE o.id=NEW.orderId AND g.sealed=1 AND NEW.createdAt>=o.createdAt) OR NOT EXISTS(SELECT 1 FROM User u JOIN TelegramAdmin a ON a.telegramId=CAST(u.telegramId AS TEXT) WHERE u.id=NEW.createdBy AND u.status='ACTIVE' AND a.isActive=1) THEN RAISE(ABORT,'invalid cancellation authority or group') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM CheckoutPaymentLedger WHERE orderId=NEW.orderId) OR EXISTS(SELECT 1 FROM CheckoutPayment WHERE orderId=NEW.orderId AND status IN('SUBMITTED','APPROVED')) OR EXISTS(SELECT 1 FROM CheckoutFinalInvoice WHERE orderId=NEW.orderId) OR EXISTS(SELECT 1 FROM Refund WHERE orderId=NEW.orderId) THEN RAISE(ABORT,'cancellation conflicts with payment or refund') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM CheckoutOrderFinance f WHERE f.orderId=NEW.orderId AND NOT(json_extract(NEW.financialSnapshot,'$.orderId') IS NOT f.orderId OR json_extract(NEW.financialSnapshot,'$.userId') IS NOT f.userId OR json_extract(NEW.financialSnapshot,'$.publicId') IS NOT f.publicId OR json_extract(NEW.financialSnapshot,'$.saleMode') IS NOT f.saleMode OR json_extract(NEW.financialSnapshot,'$.orderState') IS NOT f.orderState OR json_extract(NEW.financialSnapshot,'$.goodsTotal') IS NOT f.goodsTotal OR json_extract(NEW.financialSnapshot,'$.firstPaymentAmount') IS NOT f.firstPaymentAmount OR json_extract(NEW.financialSnapshot,'$.goodsPaid') IS NOT f.goodsPaid OR json_extract(NEW.financialSnapshot,'$.unpaidGoods') IS NOT f.unpaidGoods OR json_extract(NEW.financialSnapshot,'$.firstPaymentDue') IS NOT f.firstPaymentDue OR json_extract(NEW.financialSnapshot,'$.firstPaymentState') IS NOT f.firstPaymentState OR json_extract(NEW.financialSnapshot,'$.goodsPaymentState') IS NOT f.goodsPaymentState OR json_extract(NEW.financialSnapshot,'$.cargoAmount') IS NOT f.cargoAmount OR json_extract(NEW.financialSnapshot,'$.cargoPaid') IS NOT f.cargoPaid OR json_extract(NEW.financialSnapshot,'$.unpaidCargo') IS NOT f.unpaidCargo OR json_extract(NEW.financialSnapshot,'$.arrivalId') IS NOT f.arrivalId OR json_extract(NEW.financialSnapshot,'$.arrivedAt') IS NOT f.arrivedAt OR json_extract(NEW.financialSnapshot,'$.cargoChargeId') IS NOT f.cargoChargeId OR json_extract(NEW.financialSnapshot,'$.cargoVersion') IS NOT f.cargoVersion OR json_extract(NEW.financialSnapshot,'$.finalInvoiceId') IS NOT f.finalInvoiceId OR json_extract(NEW.financialSnapshot,'$.finalInvoiceTotal') IS NOT f.finalInvoiceTotal OR json_extract(NEW.financialSnapshot,'$.finalDue') IS NOT f.finalDue OR json_extract(NEW.financialSnapshot,'$.finalPaymentState') IS NOT f.finalPaymentState OR json_extract(NEW.financialSnapshot,'$.financiallySettled') IS NOT f.financiallySettled OR json_extract(NEW.financialSnapshot,'$.fulfillmentAllowed') IS NOT f.fulfillmentAllowed OR json_extract(NEW.financialSnapshot,'$.finalPaymentEnabled') IS NOT f.finalPaymentEnabled OR json_extract(NEW.financialSnapshot,'$.cargoEnabled') IS NOT f.cargoEnabled OR json_extract(NEW.financialSnapshot,'$.cancellationId') IS NOT f.cancellationId OR json_extract(NEW.financialSnapshot,'$.cancelledAt') IS NOT f.cancelledAt OR json_extract(NEW.financialSnapshot,'$.paymentAllowed') IS NOT f.paymentAllowed)) THEN RAISE(ABORT,'invalid cancellation financial snapshot') END; SELECT CASE WHEN json_array_length(NEW.reservationSnapshot)=0 OR json_array_length(NEW.reservationSnapshot)<>(SELECT COUNT(*) FROM CheckoutOrderItem WHERE orderId=NEW.orderId) OR (SELECT COUNT(DISTINCT json_extract(value,'$.id')) FROM json_each(NEW.reservationSnapshot))<>json_array_length(NEW.reservationSnapshot) OR EXISTS(SELECT 1 FROM CheckoutOrderItem i WHERE i.orderId=NEW.orderId AND NOT EXISTS(SELECT 1 FROM json_each(NEW.reservationSnapshot) j WHERE json_extract(j.value,'$.id')=i.id AND json_extract(j.value,'$.productId')=i.productId AND json_extract(j.value,'$.variantId')=i.variantId AND json_extract(j.value,'$.quantity')=i.quantity AND json_extract(j.value,'$.inventoryReservedQuantity')=i.inventoryReservedQuantity)) THEN RAISE(ABORT,'invalid reservation snapshot') END; END;
CREATE TRIGGER CheckoutStockRelease_insert BEFORE INSERT ON CheckoutStockRelease BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM CheckoutCancellation c JOIN CheckoutOrderItem i ON i.orderId=c.orderId JOIN ProductVariant v ON v.id=i.variantId WHERE c.id=NEW.cancellationId AND c.orderId=NEW.orderId AND c.sealed=0 AND i.id=NEW.itemId AND i.saleMode='IN_STOCK' AND i.inventoryReservedQuantity=NEW.quantity AND i.variantId=NEW.variantId AND v.productId=i.productId AND v.isActive=1 AND typeof(v.stock)='integer' AND v.stock=NEW.stockBefore AND NEW.createdAt=c.createdAt) THEN RAISE(ABORT,'unsafe reservation release') END; END;
CREATE TRIGGER CheckoutStockRelease_apply AFTER INSERT ON CheckoutStockRelease BEGIN UPDATE ProductVariant SET stock=NEW.stockAfter,updatedAt=NEW.createdAt WHERE id=NEW.variantId; INSERT INTO AuditLog(id,actorId,action,entityType,entityId,metadata,createdAt) SELECT 'stock-release:'||NEW.id,createdBy,'linked-order.stock-released','CheckoutStockRelease',NEW.id,json_object('orderId',NEW.orderId,'itemId',NEW.itemId,'quantity',NEW.quantity,'stockBefore',NEW.stockBefore,'stockAfter',NEW.stockAfter),NEW.createdAt FROM CheckoutCancellation WHERE id=NEW.cancellationId; END;
CREATE TRIGGER CheckoutCancellation_seal BEFORE UPDATE ON CheckoutCancellation BEGIN SELECT CASE WHEN OLD.sealed<>0 OR NEW.sealed<>1 OR NEW.id IS NOT OLD.id OR NEW.orderId IS NOT OLD.orderId OR NEW.reason IS NOT OLD.reason OR NEW.createdBy IS NOT OLD.createdBy OR NEW.createdAt IS NOT OLD.createdAt OR NEW.operationKey IS NOT OLD.operationKey OR NEW.requestFingerprint IS NOT OLD.requestFingerprint OR NEW.financialSnapshot IS NOT OLD.financialSnapshot OR NEW.reservationSnapshot IS NOT OLD.reservationSnapshot THEN RAISE(ABORT,'cancellation immutable except sealing') END; SELECT CASE WHEN (SELECT COUNT(*) FROM CheckoutStockRelease WHERE cancellationId=OLD.id)<>(SELECT COUNT(*) FROM CheckoutOrderItem WHERE orderId=OLD.orderId AND inventoryReservedQuantity>0) OR EXISTS(SELECT 1 FROM CheckoutOrderItem i WHERE i.orderId=OLD.orderId AND i.inventoryReservedQuantity>0 AND NOT EXISTS(SELECT 1 FROM CheckoutStockRelease r WHERE r.cancellationId=OLD.id AND r.itemId=i.id AND r.quantity=i.inventoryReservedQuantity)) OR NOT EXISTS(SELECT 1 FROM AuditLog WHERE action='linked-order.cancelled' AND entityType='CheckoutCancellation' AND entityId=OLD.id AND actorId=OLD.createdBy) THEN RAISE(ABORT,'incomplete cancellation release or audit') END; END;
CREATE TRIGGER CheckoutCancellation_delete BEFORE DELETE ON CheckoutCancellation BEGIN SELECT RAISE(ABORT,'cancellation history immutable'); END;
CREATE TRIGGER CheckoutStockRelease_update BEFORE UPDATE ON CheckoutStockRelease BEGIN SELECT RAISE(ABORT,'release history immutable'); END;
CREATE TRIGGER CheckoutStockRelease_delete BEFORE DELETE ON CheckoutStockRelease BEGIN SELECT RAISE(ABORT,'release history immutable'); END;
CREATE TRIGGER CheckoutPayment_cancelled BEFORE INSERT ON CheckoutPayment WHEN EXISTS(SELECT 1 FROM CheckoutCancellation WHERE orderId=NEW.orderId) BEGIN SELECT RAISE(ABORT,'linked order cancelled'); END;
CREATE TRIGGER CheckoutPaymentLedger_cancelled BEFORE INSERT ON CheckoutPaymentLedger WHEN EXISTS(SELECT 1 FROM CheckoutCancellation WHERE orderId=NEW.orderId) BEGIN SELECT RAISE(ABORT,'linked order cancelled'); END;
CREATE TRIGGER CheckoutArrival_cancelled BEFORE INSERT ON CheckoutArrival WHEN EXISTS(SELECT 1 FROM CheckoutCancellation WHERE orderId=NEW.orderId) BEGIN SELECT RAISE(ABORT,'linked order cancelled'); END;
CREATE TRIGGER CheckoutCargoCharge_cancelled BEFORE INSERT ON CheckoutCargoCharge WHEN EXISTS(SELECT 1 FROM CheckoutCancellation WHERE orderId=NEW.orderId) BEGIN SELECT RAISE(ABORT,'linked order cancelled'); END;
CREATE TRIGGER CheckoutFinalInvoice_cancelled BEFORE INSERT ON CheckoutFinalInvoice WHEN EXISTS(SELECT 1 FROM CheckoutCancellation WHERE orderId=NEW.orderId) BEGIN SELECT RAISE(ABORT,'linked order cancelled'); END;
CREATE TRIGGER CheckoutPayment_cancelled_review BEFORE UPDATE ON CheckoutPayment WHEN EXISTS(SELECT 1 FROM CheckoutCancellation WHERE orderId=OLD.orderId) BEGIN SELECT RAISE(ABORT,'linked order cancelled'); END;
CREATE TRIGGER revision_CheckoutCancellation_INSERT AFTER INSERT ON CheckoutCancellation BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutCancellation_UPDATE AFTER UPDATE ON CheckoutCancellation BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutCancellation_DELETE AFTER DELETE ON CheckoutCancellation BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutStockRelease_INSERT AFTER INSERT ON CheckoutStockRelease BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutStockRelease_UPDATE AFTER UPDATE ON CheckoutStockRelease BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutStockRelease_DELETE AFTER DELETE ON CheckoutStockRelease BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
DROP VIEW CheckoutOrderFinance;
CREATE VIEW CheckoutOrderFinance AS
SELECT o.id orderId,g.userId,o.publicId,o.saleMode,CASE WHEN x.id IS NOT NULL THEN 'CANCELLED' ELSE o.state END orderState,o.goodsTotal,o.firstPaymentAmount,
 COALESCE(f.goodsAmount,0)+COALESCE(l.goodsAmount,0) goodsPaid,
 o.goodsTotal-COALESCE(f.goodsAmount,0)-COALESCE(l.goodsAmount,0) unpaidGoods,
 o.firstPaymentAmount-COALESCE(f.goodsAmount,0) firstPaymentDue,
 CASE WHEN f.id IS NOT NULL THEN 'CONFIRMED' WHEN EXISTS(SELECT 1 FROM CheckoutPayment p WHERE p.orderId=o.id AND p.phase='FIRST' AND p.status='SUBMITTED') THEN 'PENDING_REVIEW' WHEN EXISTS(SELECT 1 FROM CheckoutPayment p WHERE p.orderId=o.id AND p.phase='FIRST' AND p.status='REJECTED') THEN 'REJECTED' ELSE 'AWAITING_PAYMENT' END firstPaymentState,
 CASE WHEN COALESCE(f.goodsAmount,0)+COALESCE(l.goodsAmount,0)=0 THEN 'UNPAID' WHEN COALESCE(f.goodsAmount,0)+COALESCE(l.goodsAmount,0)=o.goodsTotal THEN 'PAID' ELSE 'PARTIALLY_PAID' END goodsPaymentState,
 c.amount cargoAmount,COALESCE(l.cargoAmount,0) cargoPaid,
 CASE WHEN c.id IS NULL THEN NULL ELSE c.amount-COALESCE(l.cargoAmount,0) END unpaidCargo,
 a.id arrivalId,a.arrivedAt,c.id cargoChargeId,c.version cargoVersion,i.id finalInvoiceId,i.totalDue finalInvoiceTotal,
 CASE WHEN i.id IS NULL THEN NULL ELSE i.totalDue-COALESCE(l.goodsAmount,0)-COALESCE(l.cargoAmount,0) END finalDue,
 CASE WHEN i.id IS NULL THEN 'UNAVAILABLE' WHEN i.totalDue=0 THEN 'SETTLED_ZERO' WHEN l.id IS NOT NULL THEN 'CONFIRMED' WHEN EXISTS(SELECT 1 FROM CheckoutPayment p WHERE p.orderId=o.id AND p.phase='FINAL' AND p.status='SUBMITTED') THEN 'PENDING_REVIEW' WHEN EXISTS(SELECT 1 FROM CheckoutPayment p WHERE p.orderId=o.id AND p.phase='FINAL' AND p.status='REJECTED') THEN 'REJECTED' ELSE 'AWAITING_PAYMENT' END finalPaymentState,
 CASE WHEN x.id IS NOT NULL THEN 0 WHEN o.saleMode='IN_STOCK' THEN CASE WHEN COALESCE(f.goodsAmount,0)=o.goodsTotal THEN 1 ELSE 0 END WHEN i.id IS NOT NULL AND i.totalDue=COALESCE(l.goodsAmount,0)+COALESCE(l.cargoAmount,0) THEN 1 ELSE 0 END financiallySettled,
 0 fulfillmentAllowed,
 CASE WHEN x.id IS NULL AND i.id IS NOT NULL AND i.totalDue>0 AND l.id IS NULL AND NOT EXISTS(SELECT 1 FROM CheckoutPayment p WHERE p.orderId=o.id AND p.phase='FINAL' AND p.status='SUBMITTED') THEN 1 ELSE 0 END finalPaymentEnabled,
 CASE WHEN x.id IS NULL AND o.saleMode='PREORDER' AND a.id IS NOT NULL AND c.id IS NULL THEN 1 ELSE 0 END cargoEnabled,
 x.id cancellationId,x.createdAt cancelledAt,CASE WHEN x.id IS NULL THEN 1 ELSE 0 END paymentAllowed
FROM CheckoutOrder o JOIN CheckoutGroup g ON g.id=o.checkoutGroupId
LEFT JOIN CheckoutPaymentLedger f ON f.orderId=o.id AND f.phase='FIRST'
LEFT JOIN CheckoutPaymentLedger l ON l.orderId=o.id AND l.phase='FINAL'
LEFT JOIN CheckoutArrival a ON a.orderId=o.id LEFT JOIN CheckoutCargoCharge c ON c.orderId=o.id
LEFT JOIN CheckoutFinalInvoice i ON i.orderId=o.id LEFT JOIN CheckoutCancellation x ON x.orderId=o.id AND x.sealed=1 WHERE g.sealed=1;
UPDATE _Revision SET version=version+1 WHERE id=1;
